#!/usr/bin/env bash
# Provision a local ONYX Health WordPress site with WP-CLI.
# Requires: PHP 8.2+, MySQL/MariaDB, WP-CLI 2.10+. Run from the repo root.
#   WP_PATH=/var/www/onyx SITE_URL=http://localhost:8088 DB_NAME=onyxwp DB_USER=onyx DB_PASS=... \
#   ADMIN_EMAIL=you@example.com ./scripts/setup.sh
# The admin password is generated by WordPress and printed once; nothing is stored in the repo.
set -euo pipefail
: "${WP_PATH:?}" "${SITE_URL:?}" "${DB_NAME:?}" "${DB_USER:?}" "${DB_PASS:?}" "${ADMIN_EMAIL:?}"
REPO="$(cd "$(dirname "$0")/.." && pwd)"
export ONYX_WORK="${ONYX_WORK:-$REPO/build-work}"
wp() { command wp --path="$WP_PATH" --user=admin "$@" 2> >(grep -v -i 'elementor' >&2); }

# --- core ---------------------------------------------------------------
mkdir -p "$WP_PATH"
command wp core download --path="$WP_PATH" --version="${WP_VERSION:-7.1.3}" --skip-content || true
[ -f "$WP_PATH/wp-config.php" ] || command wp config create --path="$WP_PATH" --dbname="$DB_NAME" --dbuser="$DB_USER" --dbpass="$DB_PASS" --dbhost="${DB_HOST:-localhost}"
command wp core is-installed --path="$WP_PATH" || command wp core install --path="$WP_PATH" --url="$SITE_URL" \
  --title="ONYX Research" --admin_user=admin --admin_email="$ADMIN_EMAIL"

# --- theme + plugins (pinned) -------------------------------------------
wp theme install hello-elementor --version=3.5.1
PLUGINS=(woocommerce:11.2.1 elementor:4.3.4 header-footer-elementor:2.9.5 wordpress-seo:28.7
  fluentform:6.2.15 ti-woocommerce-wishlist:2.13.0 click-to-chat-for-whatsapp:4.45 all-in-one-wp-migration:7.112)
for p in "${PLUGINS[@]}"; do wp plugin install "${p%%:*}" --version="${p##*:}" --activate; done

# --- custom code (symlink from repo) ------------------------------------
ln -sfn "$REPO/wp-content/themes/onyx-child" "$WP_PATH/wp-content/themes/onyx-child"
for p in onyx-core onyx-crypto-gateway; do ln -sfn "$REPO/wp-content/plugins/$p" "$WP_PATH/wp-content/plugins/$p"; done
wp theme activate onyx-child
wp plugin activate onyx-core onyx-crypto-gateway
wp rewrite structure '/%postname%/' && wp option update woocommerce_permalinks \
  '{"product_base":"/product","category_base":"peptides","tag_base":"product-tag","attribute_base":"","use_verbose_page_rules":false}' --format=json

# --- catalogue -----------------------------------------------------------
mkdir -p "$ONYX_WORK/import" "$ONYX_WORK/live"
cp "$REPO/data/products/onyx-products-woocommerce.csv" "$REPO/data/products/media-urls.json" "$ONYX_WORK/import/"
[ -f "$ONYX_WORK/live/products.json" ] || cp "$REPO/data/products/live-products.json" "$ONYX_WORK/live/products.json"
wp eval-file scripts/lib/import-products.php
wp eval-file scripts/lib/create-variations.php
wp eval-file scripts/lib/import-media.php
wp eval-file scripts/lib/create-shipping-zones.php data/shipping-zones.json

# --- forms, site config, pages ------------------------------------------
wp eval-file scripts/lib/create-forms.php
wp eval-file scripts/lib/configure-site.php
wp eval-file scripts/lib/import-templates.php data/elementor
wp eval-file scripts/lib/import-elementor-pages.php data/elementor/manifest.json
wp option update show_on_front page && wp option update page_on_front "$(wp post list --post_type=page --name=home --field=ID)"
wp eval-file scripts/lib/apply-seo.php data/seo-pages.json
wp elementor flush-css || true
wp rewrite flush
echo "Done. Set the crypto wallet addresses in WooCommerce > Settings > Payments > Crypto (USDT / USDC)."
